const r="https://api.libertyroam.com",s={packages:{}},n=60*60*1e3,p=async(a=5)=>{const c=Date.now(),e=s.packages[a];if(e&&c-e.timestamp<n)return e.data;try{const t=await fetch(`${r}/packages?limit=${a}`);if(!t.ok)throw new Error(`Error fetching packages: ${t.statusText}`);const o=await t.json();return s.packages[a]={data:o,timestamp:c},o}catch(t){throw console.error("Failed to fetch packages:",t),t}};export{p as getPackages};
